write.solution:
#!/bin/bash

# swap.sh: print the second half of $1 then the first half

s=$1
n=$(( ${#s} / 2 ))
first=${s:0:n}
second=${s:n}
echo "$second$first"

#!/bin/bash

# mkbackup.sh: copy a file into a backup directory next to it

pathname=$1
dir=${pathname%/*}
name=${pathname##*/}

backupdir=$dir/backup
mkdir "$backupdir"
cp "$pathname" "$backupdir/$name.bak"
chmod 400 "$backupdir/$name.bak"
echo "backed up $name to $backupdir"
